    uint4* p = reinterpret_cast<uint4*>(smem_raw + (sbase - sraw));
    const int n = (stages * stageBytes) / 16;
    for (int i = threadIdx.x; i < n; i += 128) {
      uint32_t h = (uint32_t)i * 2654435761u;
      p[i] = make_uint4(0x3e000000u | ((h >> 9) & 0x3fffff), 0x3e000000u | ((h >> 5) & 0x3fffff), 0x3e000000u | ((h >> 7) & 0x3fffff), 0x3e000000u | ((h >> 3) & 0x3fffff));
    }
