  cluster_sync();
  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint32_t tmem = tmem_slot;

  if (c.feed && warp == 0 && lane == 0) {
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
      if (i >= stages) mbar_wait(smem_u32(&empty[s]), ((i / stages) - 1) & 1);
      const uint32_t fl = smem_u32(&full[s]);
      const uint32_t fb = mapa_to(fl, 0);
      if (rank == 0) asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(fl), "r"(2 * stageBytes) : "memory");
      const uint32_t a = sbase + s * stageBytes, b = a + kbs * kWBlk;
      const int kb0 = (i * kbs) % kKB;
