          for (int k = 0; k < 4; ++k) {
            const uint32_t acc = (i | j | k) != 0;
            mma2(tmem, da + 2 * k, db1 + 2 * k, idesc1, acc);
            if (e2 > 0) mma2(tmem + 256, da + 2 * k, db2 + 2 * k, idesc2, acc);
          }
        }
