extern "C" int run_cfg(const float* W, const float* emb, unsigned long long* out, int feed, int mma, int kbs, int stages,
                       int e1, int e2, int nk, int grid, int reps) {
  Cfg c{feed, mma, kbs, stages, e1, e2, nk, e2 > 0 ? 512 : (2 * e1 <= 128 ? 128 : 256)};
  const size_t eBlk = (size_t)(e1 + e2) * 128, sb = (size_t)kbs * (kWBlk + eBlk), dyn = stages * sb + 1024;
  if (dyn > 232000 || stages > kMaxStages || nk % kbs) return 430;
  CUtensorMap mW, mE1, mE2;
  cuuint64_t dW[3] = {(cuuint64_t)kBK, (cuuint64_t)kN, (cuuint64_t)kKB}, sW[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bW[3] = {kBK, kRows, (cuuint32_t)kbs}, es[3] = {1, 1, 1};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 431;
  cuuint64_t dE[2] = {(cuuint64_t)kD, 1024}, sE[1] = {(cuuint64_t)kD * 4};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)e1}, bE2[2] = {kBK, (cuuint32_t)(e2 > 0 ? e2 : 8)};
  if (cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 432;
  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 433;
  cudaFuncSetAttribute(bench_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)dyn);
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid); cfg.blockDim = dim3(128); cfg.dynamicSmemBytes = dyn; cfg.stream = 0;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = 1;
  for (int r = 0; r < reps; ++r) {
    cudaError_t e = cudaLaunchKernelEx(&cfg, bench_kernel, mW, mE1, mE2, c, out);
    if (e != cudaSuccess) return 500 + (int)e;
  }
  return (int)cudaDeviceSynchronize();
}
